/*
  Hand-drawn "boil": two positions, half a dash period apart, held 0.5s each.
  steps(2) samples progress at 0 and 0.5, so the -10 endpoint (one full
  --sketch-dash period, which would land back where it started) is never shown.
*/
@keyframes sketch-dash-boil {
  to {
    stroke-dashoffset: -10;
  }
}

@keyframes sketch-icon-wiggle {
  0%,
  100% {
    transform: rotate(-5deg);
  }

  50% {
    transform: rotate(5deg);
  }
}

"use client";

import "./sketch.css";

import {
  type ReactNode,
  useContext,
  useId,
  useLayoutEffect,
  useMemo,
  useState,
} from "react";
import rough from "roughjs";
import type { Options } from "roughjs/bin/core";
import {
  createRoundedRectanglePath,
  createSeed,
  createUnderlinePath,
  DEFAULT_SEED,
  DEFAULT_STROKE_WIDTH,
  getBorderRadius,
  getCssSketchOptions,
  getPaddingBoxSize,
  MIN_STROKE_WIDTH,
  SketchContext,
  type SketchOutline,
  type SketchOutlineOptions,
  type SketchShape,
  type SketchTheme,
} from "./utils/sketch";

export type SketchProviderProps = {
  children: ReactNode;
  options?: Partial<Options>;
  seed?: number;
};

export type { SketchOutline, SketchOutlineOptions, SketchShape } from "./utils/sketch";

export function SketchProvider({
  children,
  options,
  seed = DEFAULT_SEED,
}: SketchProviderProps) {

  const value = useMemo(
    () => ({
      options: options as Partial<Options>,
      seed,
    }),
    [options, seed],
  );

  return <SketchContext.Provider value={value}>{children}</SketchContext.Provider>;
}


export function useSketchOutline(options: SketchOutlineOptions = {}): SketchOutline {
  const { opacity, shape = "rectangle", ...roughOptions } = options;
  const theme = useSketch();
  const [svg, setSvg] = useState<SVGSVGElement | null>(null);
  const instanceId = useId();

  const seed = useMemo(() => createSeed(theme.seed, instanceId), [instanceId, theme.seed]);

  useLayoutEffect(() => {
    const target = svg?.parentElement;

    if (!svg || !target) {
      return;
    }

    let frame = 0;
    const draw = () => {
      const { height, width } = getPaddingBoxSize(target);

      if (width <= 0 || height <= 0) {
        return;
      }

      const drawing = rough.svg(svg);
      const drawingOptions = {
        ...theme.options,
        ...getCssSketchOptions(target),
        ...roughOptions,
        seed,
      };
      const strokeWidth = Math.max(
        MIN_STROKE_WIDTH,
        drawingOptions.strokeWidth ?? DEFAULT_STROKE_WIDTH,
      );
      const path = getSketchPath(shape, target, width, height, strokeWidth);
      const drawn = drawing.path(path, { ...drawingOptions, strokeWidth });

      svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
      svg.replaceChildren(drawn);
    };

    const scheduleDraw = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(draw);
    };

    const observer = new ResizeObserver(scheduleDraw);
    observer.observe(target);
    const attributeObserver = new MutationObserver(scheduleDraw);
    attributeObserver.observe(target, {
      attributeFilter: ["class", "style"],
      attributes: true,
    });
    scheduleDraw();

    return () => {
      cancelAnimationFrame(frame);
      attributeObserver.disconnect();
      observer.disconnect();
    };
  }, [seed, shape, svg]);

  return {
    ref: setSvg,
    style: {
      height: "100%",
      left: 0,
      opacity,
      // Rough's wobble swings past the viewBox; the default svg clip shaves it to a hairline.
      overflow: "visible",
      pointerEvents: "none",
      position: "absolute",
      top: 0,
      width: "100%",
    },
  };
}

export function useSketchBg(options: SketchOutlineOptions = {}): SketchOutline {
  return useSketchOutline({
    fill: "currentColor",
    fillStyle: "hachure",
    fillWeight: 0.4,
    hachureGap: 4,
    stroke: "transparent",
    opacity: 0.5,
    ...options,
  });
}

function getSketchPath(
  shape: SketchShape,
  target: Element,
  width: number,
  height: number,
  strokeWidth: number,
): string {
  if (shape === "underline") {
    return createUnderlinePath(width, height, strokeWidth);
  }

  return createRoundedRectanglePath(width, height, getBorderRadius(target), strokeWidth);
}

function useSketch(): SketchTheme {
  const theme = useContext(SketchContext);

  if (theme === null) {
    throw new Error("Sketch components must be rendered inside SketchProvider.");
  }

  return theme;
}

import { createContext, type CSSProperties, type Ref } from "react";
import type { Options } from "roughjs/bin/core";

export const DEFAULT_SEED = 20_260_828;
export const DEFAULT_STROKE_WIDTH = 1.6;
export const MIN_STROKE_WIDTH = 1;

export type SketchTheme = {
	options: Partial<Options>;
	seed: number;
};

export const SketchContext = createContext<SketchTheme | null>(null);

export type SketchShape = "rectangle" | "underline";

export type SketchOutlineOptions = Partial<Options> & {
	borderRadius?: number;
	opacity?: number;
	shape?: SketchShape;
};

export type SketchOutline = {
	ref: Ref<SVGSVGElement>;
	style: CSSProperties;
};

export function createSeed(seed: number, instanceId: string): number {
	let hash = seed;

	for (let index = 0; index < instanceId.length; index += 1) {
		hash = (hash << 5) - hash + instanceId.charCodeAt(index);
		hash |= 0;
	}

	return (hash >>> 0) % 2_147_483_647 || 1;
}

export function getCssSketchOptions(target: Element): Partial<Options> {
	const styles = getComputedStyle(target);
	const bowing = readCssNumber(styles, "--sketch-bowing");
	const roughness = readCssNumber(styles, "--sketch-roughness");
	const stroke = styles.getPropertyValue("--sketch-stroke").trim();
	const strokeWidth = readCssNumber(styles, "--sketch-stroke-width");
	const disableMultiStroke = readCssBoolean(styles, "--sketch-disable-multi-stroke");
	const preserveVertices = readCssBoolean(styles, "--sketch-preserve-vertices");
	const fill = styles.getPropertyValue("--sketch-fill").trim();
	const fillStyle = styles.getPropertyValue("--sketch-fill-style").trim();

	return {
		...(bowing === undefined ? {} : { bowing }),
		...(disableMultiStroke === undefined ? {} : { disableMultiStroke }),
		...(fill === "" ? {} : { fill }),
		...(fillStyle === "" ? {} : { fillStyle }),
		...(roughness === undefined ? {} : { roughness }),
		...(preserveVertices === undefined ? {} : { preserveVertices }),
		...(stroke === "" ? {} : { stroke }),
		...(strokeWidth === undefined ? {} : { strokeWidth }),
	};
}

export function getBorderRadius(target: Element): number {
	return Number.parseFloat(getComputedStyle(target).borderTopLeftRadius) || 0;
}

/**
 * Measures the padding box rather than the border box.
 *
 * The outline `<svg>` is an absolutely positioned `100%` overlay, which resolves
 * against the padding box. Feeding it a border-box viewBox letterboxes the
 * drawing and scales the stroke down on any bordered element.
 */
export function getPaddingBoxSize(target: Element): { height: number; width: number } {
	const styles = getComputedStyle(target);
	const rect = target.getBoundingClientRect();

	return {
		height: rect.height - readPixels(styles.borderTopWidth) - readPixels(styles.borderBottomWidth),
		width: rect.width - readPixels(styles.borderLeftWidth) - readPixels(styles.borderRightWidth),
	};
}

function readPixels(value: string): number {
	return Number.parseFloat(value) || 0;
}

export function createRoundedRectanglePath(
	width: number,
	height: number,
	radius: number,
	strokeInset: number,
): string {
	const left = strokeInset;
	const top = strokeInset;
	const right = width - strokeInset;
	const bottom = height - strokeInset;
	const cornerRadius = Math.min(radius, (right - left) / 2, (bottom - top) / 2);

	if (cornerRadius === 0) {
		return `M ${left} ${top} H ${right} V ${bottom} H ${left} Z`;
	}

	return [
		`M ${left + cornerRadius} ${top}`,
		`H ${right - cornerRadius}`,
		`Q ${right} ${top} ${right} ${top + cornerRadius}`,
		`V ${bottom - cornerRadius}`,
		`Q ${right} ${bottom} ${right - cornerRadius} ${bottom}`,
		`H ${left + cornerRadius}`,
		`Q ${left} ${bottom} ${left} ${bottom - cornerRadius}`,
		`V ${top + cornerRadius}`,
		`Q ${left} ${top} ${left + cornerRadius} ${top}`,
		"Z",
	].join(" ");
}

export function createUnderlinePath(
	width: number,
	height: number,
	strokeInset: number,
): string {
	const bottom = height - strokeInset;

	return `M ${strokeInset} ${bottom} H ${width - strokeInset}`;
}

function readCssNumber(styles: CSSStyleDeclaration, property: string): number | undefined {
	const value = Number.parseFloat(styles.getPropertyValue(property));

	if (Number.isNaN(value)) {
		return undefined;
	}

	return value;
}

function readCssBoolean(styles: CSSStyleDeclaration, property: string): boolean | undefined {
	const value = styles.getPropertyValue(property).trim();

	if (value === "true") {
		return true;
	}

	if (value === "false") {
		return false;
	}

	return undefined;
}
